window.MONSTER_CHUNK_6 = [{"name":"Ghost Scorpion","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"vermin","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":12,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+1 natural, +1 size","hp":13,"hd":"2d8+4","hdvalue":2,"fort":5,"ref":0,"will":0,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +2 (1d3), sting +2 (1d3 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"}],"strength":10,"dexterity":11,"constitution":14,"wisdom":10,"charisma":2,"baseatk":1,"cmb":0,"cmd":10,"cmd_special":"+12 vs. trip","skills":[{"skill":"Perception","value":4},{"skill":"Stealth","value":8}],"environments":["any underground","warm deserts"],"organizations":["solitary","pair","nest (3-6)"],"treasure":"none","description_visual":"This outsized scorpion has a translucent shell, allowing one to see through to the creature's internal organs.","group":"Scorpion","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 13; frequency 1/round for 4 rounds; effect 1 Str damage; cure 1 save."}],"description":"So named for their eerie, translucent carapaces, ghost scorpions are nocturnal desert hunters. A ghost scorpion's body is 3 ft. long with a 3-foot long tail, and it weighs 45 pounds.","ecology":"","habitat_society":""},{"name":"Giant Centipede","cr":0.5,"xp":200,"alignment":"N","size":"Medium","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":5,"hd":"1d8+1","hdvalue":1,"fort":3,"ref":2,"will":0,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":40}],"melee":"bite +2 (1d6-1 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"}],"strength":9,"dexterity":15,"constitution":12,"wisdom":10,"charisma":2,"baseatk":0,"cmb":-1,"cmd":11,"cmd_special":"can't be tripped","feats":[{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":4},{"skill":"Stealth","value":10}],"environments":["temperate forests","temperate underground","warm forests","warm underground"],"organizations":["solitary","pair","colony (3-6)"],"treasure":"none","description_visual":"This lengthy, segmented horror writhes and twists, pulsing its venomous mandibles in search of prey.","group":"Centipede","source":"PFRPG Bestiary","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 13; frequency 1/round for 6 rounds; effect 1d3 Dex damage; cure 1 save. The save DC is Constitution-based and includes a +2 racial bonus."}],"description":"Giant centipedes attack nearly any living creatures with their poisonous jaws. These creatures adapt to many environments and feed voraciously on the local fauna, including humanoids. The coloration of giant centipedes mirrors that of normal centipedes and spans the spectrum, ranging from dull hues to bright reds and fiery oranges. Other species of giant centipedes exist as well, some smaller but most quite a bit larger. You can adjust the stats given here by changing Hit Dice and size (changing Strength, Dexterity, and Constitution as appropriate) to represent a wide range of giant centipede species. The following table lists the most common variants. Species CR Size H D House centipede 1/8 Tiny 1d8 Sewer centipede 1/4 Small 1d8 Hissing centipede 1 Large 2d8 Giant whiptail centipede 2 Huge 4d8 Great forest centipede 6 Gargantuan 7d8 Titan centipede 9 Colossal 10d8.","ecology":"","habitat_society":""},{"name":"Giant Cockroach","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"vermin","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":14,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+1 Dex, +2 natural, +1 size","hp":8,"hd":"1d8+4","hdvalue":1,"fort":6,"ref":1,"will":0,"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30},{"type":"fly","speed":40,"maneuverability":"poor"}],"melee":"bite +1 (1d4)","space":"5 ft.","reach":"5 ft.","strength":11,"dexterity":12,"constitution":19,"wisdom":11,"charisma":2,"baseatk":0,"cmb":-1,"cmd":10,"feats":[{"feat":"Diehard","type":"bonus"},{"feat":"Endurance","type":"bonus"}],"skills":[{"skill":"Climb","value":8},{"skill":"Fly","value":-1},{"skill":"Perception","value":4},{"skill":"Stealth","value":9}],"sq":[{"type":"hold breath"}],"environments":["any land"],"organizations":["solitary","intrusion (2-20)"],"treasure":"none","description_visual":"A dog-sized cockroach skitters forth, greedily clicking its filthslicked mandibles.","group":"Cockroach","source":"PFRPG Bestiary 2","description":"Species CR Size HD Giant hissing cockroach 1 Medium 2 Venomroach 3 Large 3 Spitting cockroach 6 Huge 6 Sawback cockroach 9 Gargantuan 8 Dragonroach 12 Colossal 10 Much like their smaller kin, giant cockroaches are extremely adaptive and exist in any place they can find a ready source of food. Giant cockroaches are not normally very violent, but readily attack if threatened or if food becomes scarce. A number of species of giant cockroach exist, as summarized on the table above. Most of these variants have additional abilities, such as poison stings.","ecology":"","habitat_society":""},{"name":"Giant Crab Spider","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":13,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 size","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":2,"will":0,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":20}],"melee":"bite +2 (1d4 plus poison)","space":"5 ft.","reach":"5 ft.","strength":10,"dexterity":15,"constitution":12,"wisdom":10,"charisma":2,"baseatk":1,"cmb":0,"cmd":12,"cmd_special":"+12 vs. trip","skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":24},{"skill":"Perception","value":4},{"skill":"Stealth","value":10,"special":"+21 when stationary"}],"environments":["temperate forests","warm forests"],"organizations":["solitary","pair","colony (3-10)"],"treasure":"incidental","description_visual":"This pale yellow spider's legs protrude on either side, giving it a very distinctive stance. The thing is the size of a large dog.","group":"Spider","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 14 (includes +2 racial bonus); frequency 1/round for 4 rounds; effect 1d2 Str; cure 1 save."}],"description":"Giant crab spiders are dangerous ambush predators that live in dense forest vegetation. Though crab spiders are not web spinners, they are truly gifted climbers and use this talent to clamber up into places where they can observe wide areas from on high. Named for their curious scuttling walk and wide-legged stance, giant crab spiders are rarely larger than a typical adult half ling.","ecology":"","habitat_society":""},{"name":"Giant Flea","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":13,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 size","hp":5,"hd":"1d8+1","hdvalue":1,"fort":3,"ref":2,"will":0,"dr":"5/slashing","immunities":["disease","mind-affecting effects"],"speed":[{"type":"land","speed":30}],"melee":"bite +2 (1d4+1 plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"disease"}],"strength":12,"dexterity":15,"constitution":13,"wisdom":11,"charisma":6,"baseatk":0,"cmb":0,"cmd":12,"skills":[{"skill":"Acrobatics","value":0,"special":"+20 when jumping"}],"sq":[{"type":"uncanny leap"}],"environments":["any land","any underground"],"organizations":["solitary","cluster (2-6)","colony (7-12)"],"treasure":"none","description_visual":"A hideous, dog-sized flea leaps about on long, gangly legs. The sharp, jagged edges of its jaws greedily clatter for blood.","group":"Flea","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Disease","kind":"Ex","details":"Bite-injury; save Fort DC 11; onset 1d3 days; frequency 1 day; effect 1 Con damage; cure 1 save."},{"type":"The save DC is Constitution-based Uncanny Leap","kind":"Ex","details":"As a full-round action, a giant flea can jump up to 120 ft. A flea can treat this jump as a charge, as long as the leap is made in a straight line."}],"description":"Much like their smaller cousins, giant fleas are hemophagous insects that live in any kind of environment where they can feed upon blood. These creatures possess surprising agility and strength. Able to leap great distances, they flit about mindlessly, looking for easy prey. A giant flea can go for several months without feeding, but then gorges after such a fast. A witch can take a giant flea as a familiar. Like all vermin, a giant flea gains 1 point of Intelligence when it becomes a familiar. A giant flea familiar grants its master a +3 bonus on Fortitude saves against disease.","ecology":"","habitat_society":""},{"name":"Giant Maggot","cr":0.5,"xp":200,"alignment":"N","size":"Medium","type":"vermin","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":9,"ac_touch":9,"ac_flat_footed":9,"ac_mods":"-1 Dex","hp":7,"hd":"1d8+3","hdvalue":1,"fort":5,"ref":-1,"will":-3,"immunities":["disease","mind-affecting effects"],"speed":[{"type":"land","speed":10},{"type":"burrow","speed":5}],"melee":"bite +0 (1d6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"regurgitate"}],"strength":10,"dexterity":8,"constitution":16,"wisdom":5,"charisma":1,"baseatk":0,"cmb":0,"cmd":9,"cmd_special":"can't be tripped","organizations":["solitary","swarm (2-12)"],"treasure":"none","description_visual":"This enormous maggot has greasy, pale flesh and a dripping, circular mouth filled with tiny, sharp teeth.","group":"Maggot","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Regurgitate","kind":"Ex","details":"Once per day, a giant maggot can empty its putrid stomach upon one creature within 5 ft. The target must make a DC 13 Fortitude save or be sickened for 1 minute (or until the target spends a full-round action with at least a gallon of water to wash off the filth). The save DC is Constitution-based."}],"description":"Voracious scavengers, giant maggots feed constantly, gorging themselves on the dead in preparation for their transformation into giant flies. Their pallid, corpulent bodies are the size of human children, and their rasping teeth are capable of eating even the bones of a corpse. Giant maggots have no legs, and move with a disturbing undulation as they crawl over their meals.\n\nGiant maggots feed for 2 weeks (often moving from one corpse to another) before entering a pupal stage, after which they emerge as giant flies.","ecology":"","habitat_society":""},{"name":"Gnome","cr":0.5,"xp":200,"race":"Gnome","classes":[{"class":"ranger","level":1}],"alignment":"NE","size":"Small","type":"humanoid","subtypes":["gnome"],"init":2,"senses":[{"type":"low-light vision"}],"ac":17,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+4 armor, +2 Dex, +1 size | +4 vs. giants","hp":9,"hd":"1d10+4","hdvalue":1,"fort":5,"ref":4,"will":1,"save_mods":"Will: +2 vs. illusions, +1 vs. fear effects","speed":[{"type":"land","speed":20}],"melee":"short sword +3 (1d4/19-20)","ranged":"composite longbow +6 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"humanoid [human] +2"},{"type":"+1 on attack rolls against goblinoid and reptilian humanoids"}],"strength":10,"dexterity":15,"constitution":16,"intelligence":10,"wisdom":13,"charisma":10,"baseatk":1,"cmb":0,"cmd":12,"feats":[{"feat":"Weapon Focus (composite longbow)"}],"skills":[{"skill":"Climb","value":2},{"skill":"Fly","value":2},{"skill":"Handle Animal","value":4},{"skill":"Heal","value":5},{"skill":"Intimidate","value":4},{"skill":"Knowledge (nature)","value":4},{"skill":"Perception","value":3},{"skill":"Stealth","value":4},{"skill":"Survival","value":5}],"languages":["Common","Gnome","Sylvan"],"sq":[{"type":"track"},{"type":"wild empathy","details":"+1"}],"environments":["any land"],"organizations":["solitary","pair","gang (3-5)"],"treasure":"potion of cure light wounds; Other Gear chain shirt, short sword, composite longbow with 20 arrows","description_visual":"A strange, multicolored creature stands before you.","source":"Core Rulebook","description":"","as_character":[{"description":"Gnomes are defined by their class levels-they don't possess racial HD.\n\nThey have the following racial traits.","racial_traits":[{"type":"Ability Score Racial Traits","value":"Gnomes are physically weak but surprisingly hardy, and their attitude makes them naturally agreeable. They gain +2 Constitution, +2 Charisma, and -2 Strength.\n\n•"},{"type":"Type","value":"Gnomes are Humanoid creatures with the gnome subtype.\n\n•"},{"type":"Size","value":"Gnomes are Small creatures and thus gain a +1 size bonus to their AC, a +1 size bonus on attack rolls, a -1 penalty to their Combat Maneuver Bonus and Combat Maneuver Defense, and a +4 size bonus on Stealth checks.\n\n•"},{"type":"Base Speed","value":"(Slow Speed) Gnomes have a base speed of 20 ft.\n\n•"},{"type":"Languages","value":"Gnomes begin play speaking Common, Gnome, and Sylvan. Gnomes with high Intelligence scores can choose from the following: Draconic, Dwarven, Elven, Giant, Goblin, and Orc. See the Linguistics skill for more information about these languages."}]}],"ecology":"","habitat_society":""},{"name":"Great Horned Owl","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"animal","init":2,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +2 natural, +1 size","hp":5,"hd":"1d8+1","hdvalue":1,"fort":3,"ref":4,"will":2,"speed":[{"type":"land","speed":10},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"2 claws +3 (1d4-1)","space":"5 ft.","reach":"5 ft.","strength":8,"dexterity":15,"constitution":13,"intelligence":2,"wisdom":15,"charisma":6,"baseatk":0,"cmb":-2,"cmd":10,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":8},{"skill":"Perception","value":10},{"skill":"Stealth","value":10}],"environments":["temperate forests"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This gray-and-white feathered owl has fluffy wings and a bulky head that makes it look larger than most owls.","group":"Owl","source":"PFRPG Bestiary 3","description":"Though great horned owls seem large, most of their apparent bulk comes from their particularly fluffy feathers and rather large heads. Great horned owls have wingspans of up to 5 ft. and weigh up to 4 pounds.\n\nGreat horned owls primarily hunt at night, locating prey through their excellent hearing. Their diet consists of rodents supplemented by smaller birds and rabbits.","ecology":"","habitat_society":""},{"name":"Grindylow","cr":0.5,"xp":200,"alignment":"CE","size":"Small","type":"aberration","subtypes":["aquatic"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +2 natural, +1 size","hp":5,"hd":"1d8+1","hdvalue":1,"fort":1,"ref":2,"will":2,"speed":[{"type":"land","speed":15},{"type":"swim","speed":30}],"speed_mod":"jet 200 ft.","melee":"spear +2 (1d6+1/x3), bite -2 (1d3)","ranged":"spear +3 (1d6+1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"tangling tentacles"}],"strength":12,"dexterity":14,"constitution":13,"intelligence":9,"wisdom":10,"charisma":9,"baseatk":0,"cmb":0,"cmd":12,"cmd_special":"+6 vs. trip","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":4},{"skill":"Stealth","value":14},{"skill":"Swim","value":13}],"languages":["Aquan"],"sq":[{"type":"amphibious"}],"environments":["any water"],"organizations":["solitary","pair","gang (3-9)","warband (10-16 with 1-2 octopus minions)","tribe (17-40 plus 1 ranger sergeant of 1st-3rd level per 20 members, 1 cleric or barbarian leader of 4th-8th level, 2-8 octopus pets, and 1-2 devilfish guardians)"],"treasure":"none","description_visual":"With a large head and numerous teeth, this unsightly creature resembles a goblin from the waist up and a greasy octopus below.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Tangling Tentacles","kind":"Ex","details":"Although a grindylow can't attack to cause damage with its six tentacles, these wriggling legs constantly writhe and reach out to tug at and trip adjacent foes. During the grindylow's turn, it can make a single trip attack against any adjacent foe as a swift action. It gains a +4 racial bonus on trip attacks made with its tangling tentacles, and if it fails to trip a foe, that creature can't attempt to trip the grindylow in retaliation."}],"description":"About 4 ft. long from head to tentacle tip, grindylows appear to be half-goblin and half-octopus, the split occurring at the waist. Grindylows are violent, ravenous creatures that use their spears to hunt or just to poke at things that scream and cry.\n\nWhile grindylows resemble goblins, they are not humanoid creatures. Nonetheless, these aquatic monsters are just as wicked as the most sadistic of goblins, and take immense pleasure in others' misfortunes and the spread of mayhem. Thanks to this twisted desire, grindylows have a nasty reputation among both other intelligent water-dwelling creatures and most land-dwelling beings.\n\nGrindylows eat whatever they can kill, giving them a rather wide selection of meals. High or low, no one is safe from the brutish assaults; tribes of merfolk have been overwhelmed by bands of grindylows, as have galleons full of experienced sailors. While obvious predators such as giant eels or sharks evoke great fear from grindylows, no enemies are more hated than the squid, be it common or giant. None are sure where this disdain stems from, but it is speculated that a squid is to an octopus for a grindylow what a dog is to a goblin dog for goblins. Incredibly fond of their similarly designed kin, grindylows believe octopuses to be the epitome of beauty, with squids being regarded as hideous freaks in comparison. There is no greater insult to a grindylow than being called a squid.\n\nWhile grindylows can take class levels to gain power, certain grindylows are freakish throwbacks to a primal age; these grindylows never cease growing, and in time can become massive beasts of Huge size. Unlike the typical grindylow, these giants can attack with all six of their tentacles and constrict with great effect. Giant grindylows are fortunately quite rare.","ecology":"","habitat_society":"","gear":"spear"},{"name":"Grippli","cr":0.5,"xp":200,"race":"Grippli","classes":[{"class":"ranger","level":1}],"alignment":"N","size":"Small","type":"humanoid","subtypes":["grippli"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+2 armor, +3 Dex, +1 size","hp":12,"hd":"1d10+2","hdvalue":1,"fort":3,"ref":5,"will":0,"speed":[{"type":"land","speed":30},{"type":"climb","speed":20}],"melee":"short sword +3 (1d4+1/19-20)","ranged":"dart +5 (1d3+1) or  net +5 (special)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"vermin +2"}],"strength":12,"dexterity":17,"constitution":13,"intelligence":12,"wisdom":12,"charisma":8,"baseatk":1,"cmb":0,"cmd":12,"feats":[{"feat":"Self-Sufficient"}],"skills":[{"skill":"Acrobatics","value":4},{"skill":"Climb","value":13},{"skill":"Handle Animal","value":3},{"skill":"Heal","value":7},{"skill":"Perception","value":5},{"skill":"Stealth","value":11,"special":"+15 in forests or marshes"},{"skill":"Survival","value":7}],"languages":["Common","Grippli"],"sq":[{"type":"swamp stride"},{"type":"track"},{"type":"wild empathy"}],"environments":["warm forests","warm marshes"],"organizations":["solitary","gang (2-5)","pack (6-11)","tribe (21-30 plus 1 cleric leader of 3rd level)"],"treasure":"none","description_visual":"Its slick skin a mottled pattern of bright colors, this agile, frog-like humanoid carries a bow and wears leather armor.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Swamp Stride","kind":"Ex","details":"A grippli can move through difficult terrain at its normal speed while within a swamp. Magically altered terrain affects a grippli normally."}],"description":"These small, intelligent, humanoid tree frogs live in primitive societies deep in the forests and marshes of the world. They hunt giant insects and eat fruits and flowers from their tree homes. They often barter with more advanced creatures for metal and gemstone ornaments.\n\nGrippli hatchlings develop into adults in less than a year. Unless they meet a savage end from a forest threat, they can live 60 years, their skin graying and losing its luster as they age. A grippli stands just over 2 ft. in height and weighs 30 pounds.","as_character":[{"description":"Gripplis are defined by their class levels-they don't possess racial Hit Dice. They have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Dexterity, +2 Wisdom, -2 Strength: Gripplis are nimble and alert, but spindly."},{"type":"Small","value":"Gripplis are Small sized."},{"type":"Fast Speed","value":"Gripplis have a base speed of 30 ft. and a base climb speed of 20 ft."},{"type":"Darkvision","value":"Gripplis can see in the dark up to 60 ft."},{"type":"Camouflage","value":"+4 Stealth in marshes or forested areas."},{"type":"Swamp Stride","value":"See above."},{"type":"Weapon Familiarity","value":"Gripplis are proficient with nets."},{"type":"Languages","value":"Gripplis speak Common and Grippli. Gripplis with high Int scores can choose from the follo."}]}],"ecology":"","habitat_society":"","gear":"leather armor, 4 darts, net, short sword"},{"name":"Half-Elf","cr":0.5,"xp":200,"race":"Half-elf","classes":[{"class":"fighter","level":1}],"alignment":"LE","size":"Medium","type":"humanoid","subtypes":["elf","human"],"init":3,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 armor, +3 Dex","hp":11,"hd":"1d10+1","hdvalue":1,"fort":3,"ref":3,"will":6,"save_mods":"+2 vs. enchantment","immunities":["sleep"],"speed":[{"type":"land","speed":30}],"melee":"longsword +3 (1d8+1/19-20)","ranged":"shortbow +4 (1d6/x3)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":17,"constitution":13,"intelligence":14,"wisdom":8,"charisma":10,"baseatk":1,"cmb":13,"cmd":25,"feats":[{"feat":"Combat Expertise"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Craft (alchemy)","value":3},{"skill":"Intimidate","value":4},{"skill":"Knowledge (arcana)","value":3},{"skill":"Perception","value":3},{"skill":"Spellcraft","value":3}],"languages":["Common"],"environments":["any land"],"organizations":["solitary","pair","gang (3-5)"],"treasure":"none","description_visual":"This lanky man sneers as he draws his sword.","source":"Core Rulebook","description":"Half-elves stand taller than humans but shorter than elves. They inherit the lean build and comely features of their elven lineage, but their skin color is dictated by their human side. While half-elves retain the pointed ears of elves, theirs are more rounded and less pronounced. A half-elf's human-like eyes tend to range a spectrum of exotic colors running from amber or violet to emerald green and deep blue.","ecology":"","habitat_society":"","gear":"chainmail, longsword, shortbow"},{"name":"Haniver","cr":0.5,"xp":200,"alignment":"N","size":"Tiny","type":"fey","subtypes":["aquatic"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":13,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+1 Dex, +2 size","hp":4,"hd":"1d6+1","hdvalue":1,"fort":1,"ref":3,"will":2,"dr":"2/cold iron","sr":11,"speed":[{"type":"land","speed":10},{"type":"fly","speed":20,"maneuverability":"average"},{"type":"swim","speed":20}],"melee":"bite +1 (1d3-1)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"misplacement"}],"spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":2,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"prestidigitation"},{"spell":"ventriloquism"}]},{"frequency":"1/day","spells":[{"spell":"scare"}]}],"strength":9,"dexterity":13,"constitution":12,"intelligence":8,"wisdom":11,"charisma":12,"baseatk":0,"cmb":-1,"cmd":8,"feats":[{"feat":"Improved Initiative"}],"skills":[{"skill":"Disable Device","value":3},{"skill":"Disguise","value":5},{"skill":"Fly","value":5},{"skill":"Perception","value":4},{"skill":"Sleight of Hand","value":7},{"skill":"Stealth","value":13},{"skill":"Swim","value":11}],"languages":["Common","Sylvan"],"sq":[{"type":"amphibious"}],"environments":["temperate coasts"],"organizations":["solitary","pair","swarm (4-12)"],"treasure":"incidental","description_visual":"This small, bizarre humanoid creature has finlike wings, strange yellow skin, and tiny black eyes burning with malevolence.","group":"Gremlin","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Misplacement","kind":"Su","details":"Hanivers are swift and curious, possessing an uncanny ability to meddle with the possessions of any character whose square they enter. Any time a haniver succeeds at a Sleight of Hand check against a creature, it also rearranges that creature's possessions. The next time that creature attempts to produce a weapon or item, it finds its possessions misplaced or disarranged; retrieving a stored item or drawing a weapon then requires a standard action instead of a move action (unless the haniver has stolen the item in question). After spending this standard action, the character takes mental inventory and is no longer affected by this ability. Occasionally, hanivers replace items they've stolen or leave their old treasures-seashells, old fish, clumps of sand-in containers or clothing they have rooted through. They do this without any added difficultly to their Sleight of Hand checks."}],"description":"Haniver gremlins haunt the stories of sailors and fishing communities, featuring prominently in parables told to naughty children by disapproving parents. A thousand such tales exist, each a variation on a common theme-the gremlins flap up from the sea, startle nasty fishermen or disobedient youths, and make off with their trinkets. Yet as is rarely the case with such tales, nearly every word of these stories—no matter how unlikely or comic—proves near to the truth. Strange, capricious fey creatures that enjoy skimming whitecaps, flipping over solitary horseshoe crabs, and suicidally teasing dolphins and sharks, hanivers endlessly indulge a mad racial curiosity. Such is their obsession that every haniver must know what is under every rock, in every basket, and beneath every hat. Should they like what they find, they typically attempt to make off with it, clinging to their prize like a beloved heirloom until the next curiosity or shiny treasure catches their attention. Hanivers have no concept of worth, though they know much of desirability, and might hang onto an item they would otherwise discard in moments if another creature-or former owner-expresses desire for it. The gremlins don't steal out of any sense of maliciousness, but rather out of curiosity and self ishness. The most intelligent occasionally even believe that they're trading, and leave behind old \"treasures\"-often strange or natural items that barely fit the description-in place of things they've claimed. Regardless, folklore advises those who have something stolen by a haniver to simply abandon it rather than face the frustration of attempting to rescue it-hence the tendency of sailors to blame the hanivers whenever something goes missing. Hanivers possess flat, leathery bodies with only a few thin bones. Most stand little more than a foot tall and 1-1/2 ft. across, and weigh less than 5 pounds.","ecology":"","habitat_society":""},{"name":"Hobgoblin","cr":0.5,"xp":200,"race":"Hobgoblin","classes":[{"class":"fighter","level":1}],"alignment":"LE","size":"Medium","type":"humanoid","subtypes":["goblinoid"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+3 armor, +2 Dex, +1 shield","hp":17,"hd":"1d10+7","hdvalue":1,"fort":5,"ref":2,"will":1,"speed":[{"type":"land","speed":30}],"melee":"longsword +4 (1d8+2/19-20)","ranged":"longbow +3 (1d8/x3)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":15,"constitution":16,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":1,"cmb":3,"cmd":15,"feats":[{"feat":"Toughness"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Perception","value":2},{"skill":"Stealth","value":5}],"languages":["Common","Goblin"],"environments":["temperate hills"],"organizations":["gang (4-9)","warband (10-24)","tribe (25+ plus 50% noncombatants, 1 sergeant of 3rd level per 20 adults, 1 or 2 lieutenants of 4th or 5th level, 1 leader of 6th-8th level, 6-12 leopards, and 1-4 ogres or 1-2 trolls)"],"treasure":"NPC Gear (studded leather armor, light steel shield, longsword, longbow with 20 arrows)","description_visual":"Standing as tall as a human, this muscular, gray-skinned creature peers about with tiny, observant eyes.","source":"PFRPG Bestiary","description":"Hobgoblins are militaristic and fecund, a combination that makes them quite dangerous in some regions. They breed quickly, replacing fallen members with new soldiers and keeping up their numbers despite the fortunes of war. They generally need little reason to declare war, but more often than not that reason is to capture new slaves- life as a slave in a hobgoblin lair is brutal and short, and new slaves are always needed to replace those who fall or are eaten. Of all the goblinoid races, the hobgoblin is by far the most civilized. They see the larger and more solitary bugbears as tools to be hired and used where appropriate, usually for specif ic missions involving assassination and stealth, and look upon their smaller goblin kin with a mix of shame and frustration. Hobgoblins admire goblin tenacity, yet their miniscule kindred's unpredictable nature and fondness for fire make them unwelcome additions to hobgoblin tribes or settlements. Nonetheless, most hobgoblin tribes include a small group of goblins, typically squatting in the most undesirable corners of the settlement. Many hobgoblin tribes combine their love of warfare with keen intellects. The science of siege engines, alchemy, and complex feats of engineering fascinate most hobgoblins, and those who are particularly skilled are treated as heroes and invariably secure high-ranking positions in the tribe. Slaves with analytical minds are quite valued, and as such raids on dwarven cities are commonplace. It is well known that hobgoblins mistrust and even despise magic, particularly arcane magic. Their shamans are treated with a mix of fear and respect, and are usually forced to live alone on the fringes of the tribe's lair. It is all but unheard of to find a hobgoblin practicing arcane magic, or as hobgoblins call it, \"elf magic.\" This is the root of their hatred of magic-the hobgoblins' hatred of elves. A hobgoblin stands 5 ft. tall and weighs 160 pounds.","as_character":[{"description":"Hobgoblins are defined by their class levels-they don't possess racial Hit Dice. All hobgoblins have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Dexterity, +2 Constitution: Hobgoblins are fast and hearty."},{"type":"Darkvision","value":"Hobgoblins can see in the dark up to 60 ft."},{"type":"Sneaky","value":"Hobgoblins gain a +4 racial bonus on Stealth checks."},{"type":"Languages","value":"All hobgoblins begin play speaking Common and Goblin. Hobgoblins with high Intelligence scores can choose any of the following bonus languages: Draconic, Dwarven, Infernal, Giant, Orc."}]}],"ecology":"","habitat_society":""},{"name":"Human Zombie","cr":0.5,"xp":200,"alignment":"NE","size":"Medium","type":"undead","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":12,"ac_touch":10,"ac_flat_footed":12,"ac_mods":"+2 natural","hp":12,"hd":"2d8+3","hdvalue":2,"fort":0,"ref":0,"will":3,"dr":"5/slashing","immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"slam +4 (1d6+4)","space":"5 ft.","reach":"5 ft.","strength":17,"dexterity":10,"wisdom":10,"charisma":10,"baseatk":1,"cmb":4,"cmd":14,"feats":[{"feat":"Toughness","type":"bonus"}],"sq":[{"type":"staggered"}],"environments":["any"],"organizations":["any"],"treasure":"none","description_visual":"This walking corpse wears only a few soiled rags, its flesh rotting off its bones as it stumbles forward, arms outstretched.","group":"Zombie","source":"PFRPG Bestiary","description":"Zombies are the animated corpses of dead creatures, forced into foul unlife via necromantic magic like animate dead. While the most commonly encountered zombies are slow and tough, others possess a variety of traits, allowing them to spread disease or move with increased speed. Zombies are unthinking automatons, and can do little more than follow orders. When left unattended, zombies tend to mill about in search of living creatures to slaughter and devour. Zombies attack until destroyed, having no regard for their own safety. Although capable of following orders, zombies are more often unleashed into an area with no command other than to kill living creatures. As a result, zombies are often encountered in packs, wandering around places the living frequent, looking for victims. Most zombies are created using animate dead. Such zombies are always of the standard type, unless the creator also casts haste or remove paralysis to create fast zombies, or contagion to create plague zombies.","ecology":"","habitat_society":""},{"name":"Ifrit","cr":0.5,"xp":200,"race":"Ifrit","classes":[{"class":"sorcerer","level":1}],"alignment":"N","size":"Medium","type":"outsider","subtypes":["native"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":13,"ac_touch":13,"ac_flat_footed":10,"ac_mods":"+3 Dex","hp":8,"hd":"1d6+2","hdvalue":1,"fort":1,"ref":3,"will":0,"resists":[{"type":"fire","value":5}],"speed":[{"type":"land","speed":30}],"melee":"scimitar +0 (1d6/18-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":2,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"burning hands"}]},{"frequency":"6/day","spells":[{"spell":"elemental ray","details":"1d6 fire"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":1,"spellsknown_concentration":2,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"burning hands"},{"spell":"mage armor"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"detect magic"},{"spell":"flare"},{"spell":"prestidigitation"}]}],"strength":10,"dexterity":16,"constitution":12,"intelligence":13,"wisdom":6,"charisma":17,"baseatk":0,"cmb":0,"cmd":13,"feats":[{"feat":"Eschew Materials","type":"bonus"},{"feat":"Martial Weapon Proficiency (scimitar)"}],"skills":[{"skill":"Bluff","value":7},{"skill":"Knowledge (arcana)","value":5},{"skill":"Spellcraft","value":5}],"languages":["Common","Gnome","Ignan"],"sq":[{"type":"bloodline arcana"},{"type":"fire affinity"}],"environments":["any land"],"organizations":["solitary","pair","gang (3-5)"],"treasure":"none","description_visual":"This muscular, fiery-skinned man has flaming hair and spotted horns upon his brow.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Fire Affinity","kind":"Ex","details":"Ifrit sorcerers with the elemental (fire) bloodline treat their Charisma score as 2 points higher for all sorcerer spells and class abilities. Ifrit spellcasters with the Fire domain use their domain powers and spells at +1 caster level."}],"description":"Ifrits are humans whose ancestry includes beings of elemental fire, such as efreet. Ifrits have pointed ears, red or mottled horns on the brow, and hair that flickers and waves as if it were af lame.\n\nAll ifrits are at some level pyromaniacs. Adoring fire in all its forms, they tend to be passionate and quick to action, with a predilection for striking first in any conf lict-a trait which keeps them alive but doesn't make them a lot of friends. Ifrits generally seek out the company of either less-powerful minions who can be browbeaten into following orders, or calm, cool individuals who can balance the ifrits out.","as_character":[{"description":"Ifrits are defined by class levels-they don't possess racial Hit Dice. Ifrits have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Dexterity, +2 Charisma, -2 Wisdom: Ifrits are passionate and quick, but also impetuous and destructive."},{"type":"Darkvision","value":"Ifrits can see in the dark up to 60 ft."},{"type":"Spell-Like Ability","value":"Burning hands 1/day (caster level equals the ifrit's total Hit Dice)."},{"type":"Energy Resistance","value":"Ifrits have fire resistance 5."},{"type":"Fire Affinity","value":"See above."},{"type":"Languages","value":"Ifrits begin play speaking Common and Ignan. Ifrits with high Intelligence scores can choose any of the following bonus languages: Aquan, Auran, Dwarven, Elven, Gnome, Halfling, and Terran."}]}],"ecology":"","habitat_society":"","gear":"scimitar"},{"name":"Isitoq","cr":0.5,"xp":200,"alignment":"NE","size":"Diminutive","type":"undead","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":15,"ac_flat_footed":14,"ac_mods":"+1 Dex, +4 size","hp":9,"hd":"2d8","hdvalue":2,"fort":0,"ref":1,"will":5,"immunities":["undead traits"],"speed":[{"type":"land","speed":5},{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"slam +6 (1d2-3), 2 wings +6 (1d1-3 plus daze)","space":"1 ft.","reach":"0 ft.","special_attacks":[{"type":"daze"},{"type":"tears of anguish"}],"strength":4,"dexterity":13,"intelligence":7,"wisdom":14,"charisma":11,"baseatk":1,"cmb":-2,"cmd":5,"cmd_special":"can't be tripped","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":15},{"skill":"Perception","value":7},{"skill":"Stealth","value":18}],"languages":["Common (can't speak)"],"sq":[{"type":"visual sensor"}],"environments":["any"],"organizations":["solitary","gang (2-8)"],"treasure":"none","description_visual":"This bloodshot eyeball trails strands of bloody nerves that fan out like flapping wings.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Daze","kind":"Ex","details":"An isitoq's nerves form grotesque wings. Any creature struck by the creature's wings must succeed at a DC 11 Will save or be dazed for 1 round as the target's mind is flooded with images of the last seconds of the isitoq's existence as a living creature. This is a mind-affecting fear effect. The save DC is Charisma-based."},{"type":"Tears of Anguish","kind":"Su","details":"As a full-round action, an isitoq can make a ranged touch attack to squirt tears into the eyes of a creature within 30 ft. If the target fails a DC 11 saving throw, it experiences the effect of the isitoq's daze ability. The save DC is Charisma-based."},{"type":"Visual Sensor","kind":"Su","details":"An isitoq's creator or master can see through its eye at a range of 60 ft., using the eye's normal vision and darkvision. The following spells have a 5% chance per caster level of the isitoq's creator of operating through the isitoq: detect chaos, detect evil, detect good, detect law, detect magic, and message. If the creator is 15th level or higher, the following spells have the same chance of functioning through the isitoq: read magic and tongues."}],"description":"Awkwardly flapping through the air, this creature constantly weeps salty tears, leaving a dripping trail behind it as it flies. Most often encountered in the company of necromancers or powerful undead creatures capable of casting spells, an isitoq serves as a companion, spy, or sometimes even a familiar. Its creator normally uses it as a sentinel, sending it flying through the halls of its laboratory, lair, or dungeon complex to watch for intruders or spy on guests and test subjects. As an isitoq's creator can see through the creature's single eye, the creator can keep watch over her domain without having to leave an inner sanctum or other heavily-guarded area. Though the isitoq's attack is itself weak, any creature struck by the floating eyeball's wings sees the last moments of life experienced by the creature from which the isitoq was created. This horror-filled vision is potent with emotion, making the victim feel as if it's experiencing its own death.\n\nCREATING AN ISITOQ A spellcaster can create an isitoq from the head of a Small or Medium corpse that has at least one intact eye. The head must be animated as a 1 Hit Die undead using animate dead (this counts toward the total HD animated by the spell and the total HD the caster can control), followed by casting clairaudience/clairvoyance or locate object to establish the sensory connection, and air walk, fly, levitate, or wind wall to give it the ability to fly. When these spells are finished, one of the head's eyes pulls itself free of its socket and becomes an isitoq. The rest of the head remains part of a corpse. An evil spellcaster with the Improved Familiar feat can gain an isitoq as a familiar at 5th level.","ecology":"","habitat_society":""},{"name":"Jackal","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"animal","init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 natural, +1 size","hp":9,"hd":"1d8+5","hdvalue":1,"fort":4,"ref":4,"will":2,"speed":[{"type":"land","speed":40}],"melee":"bite +2 (1d4+1 plus trip)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"opportunistic bite"}],"strength":13,"dexterity":15,"constitution":14,"intelligence":2,"wisdom":13,"charisma":6,"baseatk":0,"cmb":3,"cmd":11,"cmd_special":"can't be tripped","feats":[{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":2},{"skill":"Perception","value":5},{"skill":"Survival","value":0,"special":"+4 when tracking by scent"}],"environments":["warm deserts","warm plains"],"organizations":["solitary","pair","pack (3-10)"],"treasure":"none","description_visual":"This sandy-colored canine resembles a slender-bodied wolf with short, graceful legs. It watches with dark brown eyes.","source":"Osirion, Legacy Of Pharaohs","special_abilities":[{"type":"Opportunistic Bite","kind":"Ex","details":"On a successful bite attack against an opponent it's flanking or that is denied its Dexterity bonus to AC, a jackal deals 1 additional point of damage."}],"description":"Jackals are usually encountered alone or as a mated pair, but sometimes they associate for a time with a small pack composed of two parents and their adult offspring, with the offspring serving a deferential support role to their parents. Although considered craven and foul by humans, jackals are relatively friendly and gentle with members of their own small packs.\n\nAttracted to the edges of human settlements in their territory, jackals often make opportunistic raids on fruit crops and vulnerable domesticated animals. They're also attracted to large deposits of garbage that they can sift through for leftover food. Jackals are remarkably adaptable, and readily forage for insects or fruit, feed on found carcasses, or hunt small or vulnerable game as the opportunity presents itself.\n\nJackals are notorious for their craftiness in evading pursuit, and they've been known to feign death when caught in order to lull opponents into complacency and gain another chance to escape. A jackal can attempt a Bluff check opposed by its opponent's Sense Motive check to play dead. If successful, after combat ends, the jackal can begin a new encounter with surprise. During the surprise round, only the jackal and any opponents who succeeded on their Sense Motive checks can act.","ecology":"","habitat_society":""},{"name":"Kangaroo","cr":0.5,"xp":200,"alignment":"N","size":"Medium","type":"animal","init":3,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+3 Dex, +2 natural","hp":6,"hd":"1d8+2","hdvalue":1,"fort":4,"ref":5,"will":0,"speed":[{"type":"land","speed":50}],"melee":"kick +1 (1d6+1 plus trip)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":16,"constitution":15,"intelligence":2,"wisdom":11,"charisma":7,"baseatk":0,"cmb":1,"cmd":14,"feats":[{"feat":"Skill Focus (Acrobatics)"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+18 when jumping"},{"skill":"Perception","value":4}],"environments":["temperate hills","temperate plains"],"organizations":["solitary","pair","mob (3-10)"],"treasure":"none","description_visual":"As tall as a grown human, this mouse-faced creature stands on powerful hind legs and has a stout tail trailing behind.","group":"Marsupial","source":"PFRPG Bestiary 3","description":"These strange-looking animals have long, pointy ears and pronounced muzzles, and their strong legs carry them about in amazing leaps. Like all marsupials, kangaroos give birth to live young (\"joeys\") that are relatively undeveloped at birth and completely helpless, and must remain within a protective pouch on the mother's belly for months before safely emerging.\n\nWhile not particularly dangerous, a kangaroo is more than capable of defending itself if cornered or when forced to protect its young, striking out at foes with a powerful kick capable of knocking unwary antagonists off their ft.\n\nA kangaroo stands over 6-1/2 ft. tall and weighs upward of 200 pounds. To represent a smaller species standing about 4 ft. tall and weighing 110 pounds, apply the young simple template or manually reduce the size from Medium to Small. Kangaroos reach maturity in less than a year and can live up to 20 years, but most individuals in the wild are hunted by predators within their first decade.","ecology":"","habitat_society":""},{"name":"Kasatha","cr":0.5,"xp":200,"race":"kasatha","classes":[{"class":"monk","level":1}],"alignment":"LN","size":"Medium","type":"humanoid","subtypes":["kasatha"],"init":3,"ac":18,"ac_touch":18,"ac_flat_footed":13,"ac_mods":"+3 Dex, +2 dodge, +3 Wis","hp":10,"hd":"1d8+2","hdvalue":1,"fort":3,"ref":5,"will":5,"speed":[{"type":"land","speed":30}],"melee":"sai +3 (1d4+1) or unarmed strike +3 (1d6+1) or flurry of blows +2 (1d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"flurry of blows"},{"type":"stunning fist","details":"1/day, DC 13"}],"strength":13,"dexterity":17,"constitution":12,"intelligence":10,"wisdom":16,"charisma":8,"baseatk":0,"cmb":1,"cmd":19,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Unarmed Strike"},{"feat":"Stunning Fist"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Climb","value":5},{"skill":"Escape Artist","value":7},{"skill":"Survival","value":4}],"languages":["Common","Kasatha"],"sq":[{"type":"desert runner"},{"type":"desert stride"},{"type":"jumper"},{"type":"multi-armed"},{"type":"stalker"}],"environments":["warm deserts"],"organizations":["solitary","band (2-6)","sect (2-20)","tribe (20-60)"],"treasure":"none","description_visual":"This strange, four-armed humanoid is sleek and muscled, with two spiked blades raised to strike.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Desert Runner","kind":"Ex","details":"A kasatha has a +4 racial bonus on Constitution checks and Fortitude saves to avoid fatigue, exhaustion, and other ill effects from running, forced marches, starvation, thirst, and hot or cold environments."},{"type":"Desert Stride","kind":"Ex","details":"A kasatha moves through nonmagical difficult terrain in desert environments at normal speed."},{"type":"Jumper","kind":"Ex","details":"A kasatha is always considered to have a running start when attempting Acrobatics checks to jump."},{"type":"Multi-Armed","kind":"Ex","details":"A kasatha has four arms. One hand is considered its primary hand; all others are considered off hands. It can use any of its hands for other purposes that require free hands."},{"type":"Stalker","kind":"Ex","details":"Perception and Stealth are class skills for a kasatha."}],"description":"Exiles from an arid world circling a red star, modern kasathas have no idea how they left their home or how to return, but they keep searching for a way back. A clannish and secretive people, they have a matriarchal society, but other races have difficulty recognizing any physical difference between females and males. Kasathas keep their mouths hidden behind clothing, and don't remove this clothing in the presence of other races. They are omnivores, but prefer meat and salty foods. Upon reaching adulthood, many kasathas leave their clans to search the world for adventure, treasure, and ways to return to their homeworld.","as_character":[{"description":"Kasathas are defined by their class levels-they don't possess racial Hit Dice. They have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Dexterity, +2 Wisdom: Kasathas are nimble and perceptive."},{"type":"Defensive Training (Ex)","value":"Kasathas have a +2 dodge bonus to Armor Class."},{"type":"Desert Runner (Ex)","value":"See the stat block above."},{"type":"Desert Stride (Ex)","value":"See the stat block above."},{"type":"Jumper (Ex)","value":"See the stat block above."},{"type":"Multi-Armed (Ex)","value":"See the stat block above. Stalker (Ex): See the stat block above."},{"type":"Languages","value":"Kasathas speak Common and Kasatha. A kasatha with a high Intelligence score can choose from the following: Dwarven, Draconic, Gnoll, Orc, and Sphinx."}]}],"ecology":"","habitat_society":"","gear":"sais [2]"},{"name":"Kitsune","cr":0.5,"xp":200,"race":"kitsune","classes":[{"class":"sorcerer","level":1}],"alignment":"N","size":"Medium","type":"humanoid","subtypes":["kitsune","shapechanger"],"init":2,"senses":[{"type":"low-light vision"}],"ac":13,"ac_touch":13,"ac_flat_footed":10,"ac_mods":"+2 Dex, +1 dodge","hp":5,"hd":"1d6-1","hdvalue":1,"fort":-1,"ref":2,"will":4,"speed":[{"type":"land","speed":30}],"melee":"bite -1 (1d4-1), mwk quarterstaff -5 (1d6-1)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":0,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"dancing lights"}]},{"frequency":"6/day","spells":[{"spell":"laughing touch"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":1,"spellsknown_concentration":0,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"charm person"},{"spell":"sleep"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":8,"dexterity":15,"constitution":8,"intelligence":12,"wisdom":14,"charisma":17,"baseatk":0,"cmb":-1,"cmd":12,"feats":[{"feat":"Dodge"},{"feat":"Eschew Materials"}],"skills":[{"skill":"Acrobatics","value":4},{"skill":"Bluff","value":7},{"skill":"Perception","value":3},{"skill":"Spellcraft","value":5},{"skill":"Stealth","value":3}],"languages":["Common","Elven","Sylvan"],"sq":[{"type":"bloodline arcana","details":"+2 DC for compulsion spells"},{"type":"change shape"},{"type":"kitsune magic"}],"environments":["any hills","any mountains","temperate forests"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This elegantly dressed woman has the head and bushy tail of well-groomed fox.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Change Shape","kind":"Su","details":"A kitsune can assume the appearance of a specific single human form of the same sex. The kitsune always takes this specific form when she uses this ability. A kitsune in human form cannot use her bite attack, but gains a +10 racial bonus on Disguise checks made to appear human. This ability otherwise functions as alter self, except that the kitsune doesn't adjust her ability scores. Kitsune Magic (Ex/Sp) Kitsune add 1 to the DC of any saving throws of enchantment spells they cast. Kitsune with a Charisma score of 11 or higher gain the following spell-like ability: 3/day-dancing lights."}],"description":"Wily but noble, kitsune are a race of shapechanging fox-folk. Each Kitsune has two shapes-a slender and attractive human form and its true form of an anthropomorphic fox. In either form, it displays physical grace and natural beauty. Most kitsune have ruddy, auburn fur and salient amber or pale blue eyes, though some are born with black, gray, or even white fur. White-furred kitsune are revered for their close connection to their spirit ancestors and typically raised as oracles. Quick-witted and nimble, kitsune delight in the creative arts, particularly riddles, storytelling, pranks, and tall tales, and have garnered a well-deserved reputation and duplicitous tricksters. They are a good-natured folk and greatly value friendship. When encountered outside human settlements, kitsune tend to live in small and remote villages run by elders of ancestral clans. In human settlements, kitsune usually remain in human form to avoid conf lict.","as_character":[{"description":"Kitsune are defined by class levels-they don't possess racial Hit Dice. Kitsune have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Dexterity, +2 Charisma, -2 Strength: Kitsune are agile and companionable, but tend to be physically weak."},{"type":"Medium","value":"Kitsune are Medium creatures and have no bonuses or penalties due to their size."},{"type":"Normal Speed","value":"Kitsune have a base speed of 30 ft."},{"type":"Low-Light Vision (Ex)","value":"Kitsune can see twice as far as humans in dim light."},{"type":"Agile (Ex)","value":"Kitsune receive a +2 racial bonus on Acrobatics checks."},{"type":"Change Shape (Su)","value":"See the stat block above."},{"type":"Kitsune Magic (Ex/Sp)","value":"See the stat block above."},{"type":"Natural Weapons (Ex)","value":"In her natural form, a kitsune has a bite attack that deals 1d4 points of damage."},{"type":"Languages","value":"Kitsune begin play speaking Common and Sylvan. Kitsune with high Intelligence scores can choose from the following: any human language, Aklo, Celestial, Elven, Gnome, and Tengu."}]}],"ecology":"","habitat_society":"","gear":"potion of cure light wounds, mwk quarterstaff"}];
